from pathlib import Path
import json, hashlib, gzip, base64, datetime

r = Path('/tmp/engine-shared-history-prefix-20261104')
g = Path('/tmp/engine-geometry-lifecycle-20261104')
repo = Path('/home/holo/line')
def file(path):
    value = path.read_bytes()
    return {'sha256': hashlib.sha256(value).hexdigest(), 'text': value.decode()}
def blob(path):
    value = path.read_bytes()
    return {'sha256': hashlib.sha256(value).hexdigest(), 'bytes': len(value),
            'gzipBase64': base64.b64encode(gzip.compress(value, mtime=0)).decode()}

qualification = json.loads((r / 'qualification.json').read_text())
assert qualification['adopt']
files = {}
for prefix, root in [('history', r), ('lifecycle', g)]:
    for path in sorted(root.iterdir()):
        if path.is_file() and path.suffix in {'.txt', '.json', '.log', '.mts', '.py', '.ts', '.rs', '.diff'} and not path.name.startswith('track-'):
            files[prefix + '/' + path.name] = file(path)

runs = {name: json.loads((r / name / 'result.json').read_text()) for name in ['screen', 'confirm', 'engine-guard', 'large-guard']}
for name in runs:
    for path in sorted((r / name).glob('*.json')):
        if path.name != 'result.json': files['history/' + name + '/' + path.name] = file(path)

for name in runs['screen']['sourceChanges']:
    path = r / 'qualified' / name
    files['candidate/' + name] = file(path) if path.exists() else {'deleted': True}
files['reference/scripts/lib/native_motion/src/frame_states.rs'] = file(r / 'reference/scripts/lib/native_motion/src/frame_states.rs')
files['history/compile_memory.mts'] = file(Path('/tmp/engine-dod-20261103/compile_memory.mts'))
for path in sorted((g / 'shadow/scripts/lib/native_motion/src').glob('*.rs')):
    files['lifecycle/shadow/src/' + path.name] = file(path)
for name in ['manifest.json', 'manifest.json.sha256']:
    files['lifecycle/shadow/' + name] = file(g / 'shadow/scripts/lib/native_motion' / name)

artifacts = {
    'referenceWasm': blob(r / 'reference/scripts/lib/native_motion/engine.wasm'),
    'candidateWasm': blob(r / 'qualified/scripts/lib/native_motion/engine.wasm'),
    'lifecycleShadowWasm': blob(g / 'shadow/scripts/lib/native_motion/engine.wasm'),
}
for cell in [61, 62]: artifacts['lifecycleTrack' + str(cell)] = blob(g / ('track-' + str(cell) + '.json'))

result = {
    'schema': 'line.engine-shared-history-prefix-study.v1',
    'createdUtc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
    'status': 'Adopted for substantial memory savings under explicit user-directed resource priority, with a disclosed native-only slowdown. Original strict performance gates did not all pass. Optimization stops after this attempt at user request.',
    'reference': {'productionCommit': '214e38a8', 'evidenceCommit': 'b2db3586',
                  'sourceSha256': runs['screen']['referenceSourceSha256'],
                  'nativeSha256': runs['screen']['artifacts'][0]['sha256']},
    'design': 'Generalize the existing 64-entry immutable saved-state chunk store to SharedPrefix<T> and reuse it for append-only collision snapshots. Clones share full chunks; appending copies a shared partial tail. Truncation bounds visibility. No new unsafe code, optional implementation, arithmetic/order/search/budget changes, or compiler-observation format changes.',
    'reproduction': 'The archived candidate source files and deletion marker are authoritative. prepare.mts records the initial mechanical migration; the final history test and README edits are included in the archived final files and review.diff. Initial pre-timing build diagnostics are retained. The frozen identities match every timing run and integrated source.',
    'lifecycleDiagnostic': json.loads((g / 'summary.json').read_text()),
    'lifecycleInterpretation': [
        'Instrumented wall spans are diagnostics, not paired timing or CPU-time evidence. Inclusive spans overlap, exclusive spans retain probe overhead, and neither calibration nor profiler overhead is silently subtracted.',
        'Grid insertion/removal shifts average roughly 2.5 elements per edit; this does not support a bulk-grid rewrite. Version walking itself is small. Actual default switches undo geometry, with zero redos.',
        'Collision-history cloning accounts for about 86% of complete-cache clone time in the instrumented default workload. This motivates sharing its immutable snapshot prefix with existing storage semantics.',
        'The demonstrated benefit is primarily memory. WASM linear-memory high-water is not live heap or process RSS. The native-only regression remains a measured tradeoff, not a passing guard.',
    ],
    'qualification': qualification,
    'runs': runs,
    'studyFiles': files,
    'artifacts': artifacts,
}
out = repo / 'docs/research/engine-shared-history-prefix-20261104.json'
out.write_text(json.dumps(result, indent=2) + '\n')
readback = json.loads(out.read_text())
for item in readback['studyFiles'].values():
    if item.get('deleted'): continue
    assert hashlib.sha256(item['text'].encode()).hexdigest() == item['sha256']
for item in readback['artifacts'].values():
    value = gzip.decompress(base64.b64decode(item['gzipBase64']))
    assert len(value) == item['bytes']
    assert hashlib.sha256(value).hexdigest() == item['sha256']
print({'path': str(out), 'bytes': out.stat().st_size, 'studyFilesVerified': len(files), 'artifactsVerified': len(artifacts)})

