//! Private diagnostic counters. Never shipped with the compiler.
use std::cell::RefCell;
#[cfg(target_arch="wasm32")]
#[link(wasm_import_module="geometry_profile")]
extern "C" {fn clock()->f64;}
#[cfg(target_arch="wasm32")]
fn now()->f64{unsafe{clock()}}
#[cfg(not(target_arch="wasm32"))]
fn now()->f64{use std::sync::OnceLock;use std::time::Instant;static START:OnceLock<Instant>=OnceLock::new();START.get_or_init(Instant::now).elapsed().as_secs_f64()*1000.0}
struct Profile{depth:usize,child:[f64;32],inclusive:[f64;24],exclusive:[f64;24],calls:[u64;24],counts:[u64;32]}
impl Profile{const fn new()->Self{Self{depth:0,child:[0.0;32],inclusive:[0.0;24],exclusive:[0.0;24],calls:[0;24],counts:[0;32]}}}
thread_local!{static PROFILE:RefCell<Profile>=const{RefCell::new(Profile::new())};}
pub(crate) struct Span{phase:usize,start:f64,depth:usize}
impl Span{pub(crate) fn new(phase:usize)->Self{let start=now();let depth=PROFILE.with_borrow_mut(|p|{let d=p.depth;p.depth+=1;p.child[d]=0.0;d});Self{phase,start,depth}}}
impl Drop for Span{fn drop(&mut self){let elapsed=now()-self.start;PROFILE.with_borrow_mut(|p|{assert_eq!(p.depth,self.depth+1);p.depth-=1;p.calls[self.phase]+=1;p.inclusive[self.phase]+=elapsed;p.exclusive[self.phase]+=elapsed-p.child[self.depth];if self.depth>0{p.child[self.depth-1]+=elapsed;}});}}
pub(crate) fn counted(i:usize,n:usize){PROFILE.with_borrow_mut(|p|p.counts[i]+=n as u64);}
pub(crate) fn timed<T>(i:usize,f:impl FnOnce()->T)->T{let _span=Span::new(i);f()}
#[no_mangle] pub extern "C" fn geometry_profile_value(group:usize,i:usize)->f64{PROFILE.with_borrow(|p|match group{0=>p.calls[i] as f64,1=>p.inclusive[i],2=>p.exclusive[i],_=>p.counts[i] as f64})}
#[no_mangle] pub extern "C" fn geometry_profile_reset(){PROFILE.with_borrow_mut(|p|{assert_eq!(p.depth,0);*p=Profile::new();});}
#[no_mangle] pub extern "C" fn geometry_profile_calibrate(n:usize){for _ in 0..n{let _span=Span::new(23);}}

