                let b = scalar.frame(frame);
                for (a, b) in [(&a.px, &b.px), (&a.py, &b.py), (&a.prevx, &b.prevx),
                    (&a.prevy, &b.prevy), (&a.vx, &b.vx), (&a.vy, &b.vy)] {
                    assert_eq!(a.map(f64::to_bits), b.map(f64::to_bits));
                }
